import fs from "node:fs";
import path from "node:path";
import prettier from "prettier";
import {
  ArrowFunction,
  ClassDeclaration,
  FunctionDeclaration,
  FunctionExpression,
  Node,
  Project,
  SourceFile,
  TypeAliasDeclaration,
  VariableDeclaration,
} from "ts-morph";
import { RegistryAutomOptions } from "./types.js";

const generatedMarker =
  "// This file is auto-generated by TypeSynth's registry autom.";

type RegistryDeclaration =
  | ReturnType<SourceFile["getInterfaces"]>[number]
  | TypeAliasDeclaration
  | ClassDeclaration;

type RegisteredValue = {
  name: string;
  sourceFile: SourceFile;
  declaration: Node;
};

type RegistryDefinition = {
  name: string;
  declaration: RegistryDeclaration;
  outputPath: string;
  values: Map<string, RegisteredValue>;
};

const normalize = (value: string) => value.replace(/\\/g, "/");
const withoutTsExtension = (value: string) =>
  value.replace(/\.d\.ts$/i, "").replace(/\.(tsx?|jsx?)$/i, "");

function jsDocTags(node: Node): Array<{ name: string; comment: string }> {
  const docs = (node as any).getJsDocs?.() ?? [];
  return docs.flatMap((doc: any) =>
    doc.getTags().map((tag: any) => ({
      name: tag.getTagName(),
      comment: (tag.getCommentText?.() ?? "").trim(),
    })),
  );
}

function parseTag(comment: string, tagName: string) {
  const parts = comment.split(/\s+/).filter(Boolean);
  if (parts.length === 0 || parts.length > 2) {
    throw new Error(
      `@${tagName} requires a registry name${tagName === "registry" ? " and an optional output path" : ""}.`,
    );
  }
  return parts;
}

function lowerCamel(value: string) {
  const words = value.match(/[A-Z]+(?=[A-Z][a-z]|$)|[A-Z]?[a-z]+|\d+/g) ?? [
    value,
  ];
  return words
    .map((word, index) =>
      index === 0
        ? word.toLowerCase()
        : word.charAt(0).toUpperCase() + word.slice(1).toLowerCase(),
    )
    .join("");
}

function isInside(root: string, candidate: string) {
  const relative = path.relative(root, candidate);
  return (
    relative === "" ||
    (!relative.startsWith("..") && !path.isAbsolute(relative))
  );
}

function getFilesRecursively(folder: string): string[] {
  return fs.readdirSync(folder, { withFileTypes: true }).flatMap((entry) => {
    const fullPath = path.join(folder, entry.name);
    return entry.isDirectory() ? getFilesRecursively(fullPath) : [fullPath];
  });
}

export function getRegistryProjectPaths(configDirectory: string) {
  const tsConfigPath = path.join(configDirectory, "tsconfig.json");
  if (!fs.existsSync(tsConfigPath)) {
    throw new Error(`Registry autom requires ${tsConfigPath}.`);
  }
  const project = new Project({ tsConfigFilePath: tsConfigPath });
  const compilerOptions = project.getCompilerOptions();
  const baseUrl = compilerOptions.baseUrl
    ? path.resolve(compilerOptions.baseUrl)
    : configDirectory;
  return {
    tsConfigPath,
    outputRoot: path.join(baseUrl, "tsynth-gen", "registry"),
    outDir: compilerOptions.outDir
      ? path.resolve(compilerOptions.outDir)
      : undefined,
  };
}

function resolveOutputPath(
  outputRoot: string,
  registryName: string,
  override?: string,
) {
  const relative = override ?? `${lowerCamel(registryName)}Registry.gen.ts`;
  if (path.isAbsolute(relative) || !relative.toLowerCase().endsWith(".ts")) {
    throw new Error(
      `Registry output "${relative}" must be a relative .ts path.`,
    );
  }
  const resolved = path.resolve(outputRoot, relative);
  if (!isInside(outputRoot, resolved)) {
    throw new Error(
      `Registry output "${relative}" cannot escape ${outputRoot}.`,
    );
  }
  return resolved;
}

function exportedRuntimeValues(sourceFile: SourceFile): RegisteredValue[] {
  const values: RegisteredValue[] = [];
  for (const declaration of [
    ...sourceFile.getFunctions(),
    ...sourceFile.getClasses(),
  ]) {
    const name = declaration.getName();
    if (name && declaration.isExported() && !declaration.isDefaultExport()) {
      values.push({ name, sourceFile, declaration });
    }
  }
  for (const statement of sourceFile.getVariableStatements()) {
    if (!statement.isExported() || statement.isDefaultExport()) continue;
    for (const declaration of statement.getDeclarations()) {
      values.push({ name: declaration.getName(), sourceFile, declaration });
    }
  }
  return values;
}

function functionLike(value: RegisteredValue) {
  if (Node.isFunctionDeclaration(value.declaration)) return value.declaration;
  if (!Node.isVariableDeclaration(value.declaration)) return undefined;
  const initializer = value.declaration.getInitializer();
  return initializer &&
    (Node.isArrowFunction(initializer) ||
      Node.isFunctionExpression(initializer))
    ? initializer
    : undefined;
}

function parameterUsesRegistry(
  fn: FunctionDeclaration | ArrowFunction | FunctionExpression,
  registry: RegistryDefinition,
) {
  if (fn.getParameters().length !== 1) return false;
  const parameter = fn.getParameters()[0];
  const type = parameter.getType();
  const symbol = type.getAliasSymbol() ?? type.getSymbol();
  return (
    symbol
      ?.getDeclarations()
      .some((declaration) => declaration === registry.declaration) ?? false
  );
}

function addValue(registry: RegistryDefinition, value: RegisteredValue) {
  const existing = registry.values.get(value.name);
  if (existing && existing.declaration !== value.declaration) {
    throw new Error(
      `Registry "${registry.name}" contains duplicate symbol "${value.name}".`,
    );
  }
  registry.values.set(value.name, value);
}

function moduleSpecifier(
  sourceFile: SourceFile,
  outputPath: string,
  project: Project,
) {
  const sourcePath = withoutTsExtension(sourceFile.getFilePath());
  const options = project.getCompilerOptions();
  const baseUrl = options.baseUrl ? path.resolve(options.baseUrl) : undefined;
  const aliases: Array<{ specifier: string; score: number }> = [];
  if (baseUrl && options.paths) {
    for (const [alias, targets] of Object.entries(options.paths)) {
      for (const target of targets) {
        const absolutePattern = normalize(path.resolve(baseUrl, target));
        const star = absolutePattern.indexOf("*");
        const source = normalize(sourcePath);
        if (star === -1) {
          if (source === withoutTsExtension(absolutePattern)) {
            aliases.push({ specifier: alias, score: absolutePattern.length });
          }
          continue;
        }
        const prefix = absolutePattern.slice(0, star);
        const suffix = withoutTsExtension(absolutePattern.slice(star + 1));
        if (source.startsWith(prefix) && source.endsWith(suffix)) {
          const wildcard = source.slice(
            prefix.length,
            source.length - suffix.length || undefined,
          );
          aliases.push({
            specifier: alias.replace("*", wildcard),
            score: prefix.length + suffix.length,
          });
        }
      }
    }
  }
  if (aliases.length > 0) {
    return aliases.sort((a, b) => b.score - a.score)[0].specifier;
  }
  let relative = normalize(path.relative(path.dirname(outputPath), sourcePath));
  if (!relative.startsWith(".")) relative = `./${relative}`;
  return relative;
}

function renderOutput(
  registries: RegistryDefinition[],
  outputPath: string,
  project: Project,
) {
  const imports = new Map<string, Set<string>>();
  for (const registry of registries) {
    for (const value of registry.values.values()) {
      const specifier = moduleSpecifier(value.sourceFile, outputPath, project);
      const names = imports.get(specifier) ?? new Set<string>();
      names.add(value.name);
      imports.set(specifier, names);
    }
  }
  const lines = [generatedMarker, ""];
  for (const [specifier, names] of [...imports].sort(([a], [b]) =>
    a.localeCompare(b),
  )) {
    lines.push(
      `import { ${[...names].sort().join(", ")} } from ${JSON.stringify(specifier)};`,
    );
  }
  if (imports.size > 0) lines.push("");
  for (const registry of registries.sort((a, b) =>
    a.name.localeCompare(b.name),
  )) {
    const members = [...registry.values.values()]
      .map((value) => ({
        value,
        member: value.name.endsWith(registry.name)
          ? value.name.slice(0, -registry.name.length)
          : value.name,
      }))
      .sort((a, b) => a.member.localeCompare(b.member));
    const seen = new Set<string>();
    for (const { member } of members) {
      if (!member)
        throw new Error(
          `Registry "${registry.name}" produced an empty member name.`,
        );
      if (seen.has(member)) {
        throw new Error(
          `Registry "${registry.name}" contains duplicate member "${member}".`,
        );
      }
      seen.add(member);
    }
    lines.push(`export enum ${registry.name}Type {`);
    for (const { member } of members)
      lines.push(`  ${member} = ${JSON.stringify(member)},`);
    lines.push("}", "", `export const ${registry.name}Map = {`);
    for (const { member, value } of members) {
      lines.push(`  [${registry.name}Type.${member}]: ${value.name},`);
    }
    lines.push("} as const;", "");
  }
  return lines.join("\n");
}

export async function runRegistryAutom(
  configDirectory: string,
  options: RegistryAutomOptions,
) {
  const { tsConfigPath, outputRoot } = getRegistryProjectPaths(configDirectory);
  const project = new Project({ tsConfigFilePath: tsConfigPath });
  const sourceFiles = project
    .getSourceFiles()
    .filter((sourceFile) => !isInside(outputRoot, sourceFile.getFilePath()));
  const registries = new Map<string, RegistryDefinition>();

  for (const sourceFile of sourceFiles) {
    const declarations: RegistryDeclaration[] = [
      ...sourceFile.getInterfaces(),
      ...sourceFile.getTypeAliases(),
      ...sourceFile.getClasses(),
    ];
    for (const declaration of declarations) {
      for (const tag of jsDocTags(declaration).filter(
        (tag) => tag.name === "registry",
      )) {
        const [name, output] = parseTag(tag.comment, "registry");
        if (registries.has(name))
          throw new Error(`Registry "${name}" is declared more than once.`);
        registries.set(name, {
          name,
          declaration,
          outputPath: resolveOutputPath(outputRoot, name, output),
          values: new Map(),
        });
      }
    }
  }

  const runtimeValues = sourceFiles.flatMap(exportedRuntimeValues);
  const handledRegistrationNodes = new Set<Node>();
  for (const sourceFile of sourceFiles) {
    const candidates: Array<{ node: Node; value?: RegisteredValue }> = [];
    for (const fn of sourceFile.getFunctions()) {
      handledRegistrationNodes.add(fn);
      candidates.push({
        node: fn,
        value: runtimeValues.find((value) => value.declaration === fn),
      });
    }
    for (const cls of sourceFile.getClasses()) {
      handledRegistrationNodes.add(cls);
      candidates.push({
        node: cls,
        value: runtimeValues.find((value) => value.declaration === cls),
      });
    }
    for (const statement of sourceFile.getVariableStatements()) {
      handledRegistrationNodes.add(statement);
      for (const declaration of statement.getDeclarations()) {
        handledRegistrationNodes.add(declaration);
        candidates.push({
          node: declaration,
          value: runtimeValues.find(
            (value) => value.declaration === declaration,
          ),
        });
      }
      for (const tag of jsDocTags(statement).filter(
        (tag) => tag.name === "register",
      )) {
        const [registryName] = parseTag(tag.comment, "register");
        const registry = registries.get(registryName);
        if (!registry)
          throw new Error(
            `@register references unknown registry "${registryName}".`,
          );
        for (const declaration of statement.getDeclarations()) {
          const value = runtimeValues.find(
            (candidate) => candidate.declaration === declaration,
          );
          if (!value)
            throw new Error(
              `@register ${registryName} requires a named runtime export.`,
            );
          addValue(registry, value);
        }
      }
    }
    for (const candidate of candidates) {
      for (const tag of jsDocTags(candidate.node).filter(
        (tag) => tag.name === "register",
      )) {
        const [registryName] = parseTag(tag.comment, "register");
        const registry = registries.get(registryName);
        if (!registry)
          throw new Error(
            `@register references unknown registry "${registryName}".`,
          );
        if (!candidate.value)
          throw new Error(
            `@register ${registryName} requires a named runtime export.`,
          );
        addValue(registry, candidate.value);
      }
    }
  }

  for (const sourceFile of sourceFiles) {
    for (const node of [sourceFile, ...sourceFile.getDescendants()]) {
      if (
        !handledRegistrationNodes.has(node) &&
        jsDocTags(node).some((tag) => tag.name === "register")
      ) {
        throw new Error(
          `@register at ${sourceFile.getFilePath()}:${node.getStartLineNumber()} requires a top-level named runtime export.`,
        );
      }
    }
  }

  if (!options.useManualRegistration) {
    for (const registry of registries.values()) {
      const validTypeNodes: Node[] = [];
      for (const value of runtimeValues) {
        const fn = functionLike(value);
        if (fn && parameterUsesRegistry(fn, registry)) {
          addValue(registry, value);
          const typeNode = fn.getParameters()[0].getTypeNode();
          if (typeNode) validTypeNodes.push(typeNode);
        }
      }
      const references = (registry.declaration as any).findReferences?.() ?? [];
      const warned = new Set<string>();
      for (const group of references) {
        for (const reference of group.getReferences()) {
          const node = reference.getNode() as Node;
          if (
            node.getFirstAncestor((ancestor) =>
              Node.isImportDeclaration(ancestor),
            )
          )
            continue;
          if (
            validTypeNodes.some(
              (typeNode) =>
                node === typeNode ||
                node.getFirstAncestor((ancestor) => ancestor === typeNode),
            )
          )
            continue;
          const key = `${node.getSourceFile().getFilePath()}:${node.getStartLineNumber()}`;
          if (warned.has(key)) continue;
          warned.add(key);
          console.warn(
            `Registry type "${registry.declaration.getName()}" has a non-inferable usage at ${key}. Use @register ${registry.name} or an exported single-argument function.`,
          );
        }
      }
    }
  }

  const byOutput = new Map<string, RegistryDefinition[]>();
  for (const registry of registries.values()) {
    const group = byOutput.get(registry.outputPath) ?? [];
    group.push(registry);
    byOutput.set(registry.outputPath, group);
  }
  const expected = new Set(
    [...byOutput.keys()].map((file) => path.resolve(file)),
  );
  for (const [outputPath, grouped] of byOutput) {
    const formatted = await prettier.format(
      renderOutput(grouped, outputPath, project),
      {
        parser: "typescript",
        filepath: outputPath,
      },
    );
    fs.mkdirSync(path.dirname(outputPath), { recursive: true });
    if (
      !fs.existsSync(outputPath) ||
      fs.readFileSync(outputPath, "utf8") !== formatted
    ) {
      fs.writeFileSync(outputPath, formatted, "utf8");
    }
  }
  if (fs.existsSync(outputRoot)) {
    const stale = getFilesRecursively(outputRoot)
      .filter((file) => file.endsWith(".ts"))
      .filter((file) => !expected.has(path.resolve(file)))
      .filter((file) =>
        fs.readFileSync(file, "utf8").startsWith(generatedMarker),
      );
    for (const file of stale) fs.unlinkSync(file);
  }

  console.log(`Generated ${registries.size} registry autom output(s).`);
}
